section.sourcecode:
id-kp-cmcCA OBJECT IDENTIFIER ::= {
   iso(1) identified-organization(3) dod(6) internet(1)
   security(5) mechanisms(5) pkix(7) kp(3) 27 }

id-kp-cmcRA OBJECT IDENTIFIER ::= {
   iso(1) identified-organization(3) dod(6) internet(1)
   security(5) mechanisms(5) pkix(7) kp(3) 28 }

id-kp-cmKGA OBJECT IDENTIFIER ::= {
   iso(1) identified-organization(3) dod(6) internet(1)
   security(5) mechanisms(5) pkix(7) kp(3) 32 }

EncryptedKey ::= CHOICE {
   encryptedValue        EncryptedValue, -- 非推奨
   envelopedData     [0] EnvelopedData }

CertRepMessage ::= SEQUENCE {
    caPubs          [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate
                        OPTIONAL,
    response            SEQUENCE OF CertResponse
}

CertResponse ::= SEQUENCE {
    certReqId           INTEGER,
    status              PKIStatusInfo,
    certifiedKeyPair    CertifiedKeyPair    OPTIONAL,
    rspInfo             OCTET STRING        OPTIONAL
    -- CertReqMsg [RFC4211]のregInfoに対して定義された
    -- id-regInfo-utf8Pairs文字列と類似のもの
}

CertifiedKeyPair ::= SEQUENCE {
   certOrEncCert       CertOrEncCert,
   privateKey      [0] EncryptedKey        OPTIONAL,
   -- エンコーディングに関するコメントは[RFC4211]を参照してください。
   publicationInfo [1] PKIPublicationInfo  OPTIONAL
}

CertOrEncCert ::= CHOICE {
   certificate     [0] CMPCertificate,
   encryptedCert   [1] EncryptedKey
}

CertStatus ::= SEQUENCE {
   certHash    OCTET STRING,
   certReqId   INTEGER,
   statusInfo  PKIStatusInfo OPTIONAL,
   hashAlg [0] AlgorithmIdentifier{DIGEST-ALGORITHM, {...}}
               OPTIONAL
}

GenMsg:    {id-it 19}, < absent >
GenRep:    {id-it 19}, CertReqTemplateContent | < absent >

CertReqTemplateValue  ::= CertReqTemplateContent

CertReqTemplateContent ::= SEQUENCE {
  certTemplate           CertTemplate,
  keySpec                Controls OPTIONAL }

Controls  ::= SEQUENCE SIZE (1..MAX) OF AttributeTypeAndValue

id-regCtrl-algId OBJECT IDENTIFIER ::= { iso(1)
   identified-organization(3) dod(6) internet(1) security(5)
   mechanisms(5) pkix(7) pkip(5) regCtrl(1) 11 }

AlgIdCtrl ::= AlgorithmIdentifier{ALGORITHM, {...}}

id-regCtrl-rsaKeyLen OBJECT IDENTIFIER ::= { iso(1)
   identified-organization(3) dod(6) internet(1) security(5)
   mechanisms(5) pkix(7) pkip(5) regCtrl(1) 12 }

RsaKeyLenCtrl ::= INTEGER (1..MAX)

GenMsg:    {id-it 22}, SEQUENCE SIZE (1..MAX) OF CRLStatus
GenRep:    {id-it 23}, SEQUENCE SIZE (1..MAX) OF
                         CertificateList  |  < absent >

CRLSource ::= CHOICE {
   dpn          [0] DistributionPointName,
   issuer       [1] GeneralNames }

CRLStatus ::= SEQUENCE {
   source       CRLSource,
   thisUpdate   Time OPTIONAL }

PollReqContent ::= SEQUENCE OF SEQUENCE {
   certReqId    INTEGER }

PollRepContent ::= SEQUENCE OF SEQUENCE {
   certReqId    INTEGER,
   checkAfter   INTEGER,  -- 秒単位の時間
   reason       PKIFreeText OPTIONAL }

PKIXCMP {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-cmp2021-88(99)}
DEFINITIONS EXPLICIT TAGS ::=
BEGIN
-- EXPORTS ALL --
IMPORTS
Certificate, CertificateList, Extensions, Name, Time, AlgorithmIdentifier, id-kp --, UTF8String -- -- 必要な場合。そうでなければコメントアウトします FROM PKIX1Explicit88 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-pkix1-explicit-88(18)} -- Nameのインポートは、CertificationRequestをPKCS #10 -- [RFC2986]からインポートする代わりに定義するために追加 -- されています。
DistributionPointName, GeneralNames, GeneralName, KeyIdentifier FROM PKIX1Implicit88 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-pkix1-implicit-88(19)}
CertTemplate, PKIPublicationInfo, EncryptedKey, CertId, CertReqMessages, Controls, AttributeTypeAndValue, id-regCtrl FROM PKIXCRMF-2005 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-crmf2005(36)} -- EncryptedKeyのインポートは、CMP Updates [RFC9480]で -- 行われた更新により追加されています。EncryptedValueは -- もはやインポートする必要がないため、ここでは削除されて -- います。
-- また、この仕様の付録Cで成文化されている、CRMFに対する -- 振る舞いの明確化も参照してください。
EnvelopedData, SignedData, Attribute FROM CryptographicMessageSyntax2004 { iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) cms-2004(24) } -- EnvelopedDataとSignedDataのインポートは、CMP Updates -- [RFC9480]で行われた更新により追加されています。 -- Attributeのインポートは、CertificationRequestを -- PKCS #10 [RFC2986]からインポートする代わりに定義する -- ために追加されています。
;
-- モジュールの残りの部分には、ローカルで定義されたOIDと -- 構成要素が含まれています。
CMPCertificate ::= CHOICE { x509v3PKCert Certificate } -- この構文は、"Certificate"の標準的なX.509の定義と -- ワイヤー上のビットレベルで互換性がありつつ、そのような -- 汎用性をサポートする必要が生じた場合に、この証明書管理 -- プロトコルの中で将来の証明書タイプ（X.509属性証明書、 -- カード検証可能な証明書、その他の種類の証明書など）を -- 扱える可能性を残しています。他の証明書タイプをサポート -- する必要性を予見しない実装は、望むなら、このASN.1 -- モジュールをコンパイルする前に上記の構造をコメント -- アウトし、次の構造の"コメントアウトを解除"しても -- よいです（MAY）。（これを行わない実装との相互運用性は、 -- この変更による影響を受けないことに注意してください。）
-- CMPCertificate ::= Certificate
PKIMessage ::= SEQUENCE { header PKIHeader, body PKIBody, protection [0] PKIProtection OPTIONAL, extraCerts [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL }
PKIMessages ::= SEQUENCE SIZE (1..MAX) OF PKIMessage
PKIHeader ::= SEQUENCE { pvno INTEGER { cmp1999(1), cmp2000(2), cmp2021(3) }, sender GeneralName, -- 送信者を識別します recipient GeneralName, -- 意図された受信者を識別します messageTime [0] GeneralizedTime OPTIONAL, -- このメッセージの生成時刻（トランスポートが"適切"である、 -- つまり受信時にもその時刻が意味を持つと送信者が考える場合 -- に使用されます） protectionAlg [1] AlgorithmIdentifier OPTIONAL, -- 保護ビットの計算に使用されるアルゴリズム senderKID [2] KeyIdentifier OPTIONAL, recipKID [3] KeyIdentifier OPTIONAL, -- 保護に使用される特定の鍵を識別するためのもの transactionID [4] OCTET STRING OPTIONAL, -- トランザクションを識別します。つまり、これは対応する -- リクエスト、レスポンス、certConf、PKIConfの各メッセージで -- 同じになります senderNonce [5] OCTET STRING OPTIONAL, recipNonce [6] OCTET STRING OPTIONAL, -- リプレイ保護を提供するために使用されるノンスです。 -- senderNonceはこのメッセージの作成者によって挿入されます。 -- recipNonceは、このメッセージの意図された受信者によって、 -- 関連するメッセージに以前挿入されたノンスです。 freeText [7] PKIFreeText OPTIONAL, -- これは、コンテキスト固有の指示を示すために使用できます -- （このフィールドは人間が読むことを意図しています） generalInfo [8] SEQUENCE SIZE (1..MAX) OF InfoTypeAndValue OPTIONAL -- これは、コンテキスト固有の情報を伝達するために使用できます -- （このフィールドは主に人間が読むことを意図していません） }
PKIFreeText ::= SEQUENCE SIZE (1..MAX) OF UTF8String -- UTF-8文字列[RFC3629]としてエンコードされたテキスト
PKIBody ::= CHOICE { -- メッセージ固有の本体要素 ir [0] CertReqMessages, --初期化リクエスト ip [1] CertRepMessage, --初期化レスポンス cr [2] CertReqMessages, --証明書発行リクエスト cp [3] CertRepMessage, --証明書発行レスポンス p10cr [4] CertificationRequest, --[RFC2986]からインポート popdecc [5] POPODecKeyChallContent, --POPチャレンジ popdecr [6] POPODecKeyRespContent, --POPレスポンス kur [7] CertReqMessages, --鍵更新リクエスト kup [8] CertRepMessage, --鍵更新レスポンス krr [9] CertReqMessages, --鍵回復リクエスト krp [10] KeyRecRepContent, --鍵回復レスポンス rr [11] RevReqContent, --失効リクエスト rp [12] RevRepContent, --失効レスポンス ccr [13] CertReqMessages, --相互証明書リクエスト ccp [14] CertRepMessage, --相互証明書レスポンス ckuann [15] CAKeyUpdAnnContent, --CA鍵更新アナウンス cann [16] CertAnnContent, --証明書アナウンス rann [17] RevAnnContent, --失効アナウンス crlann [18] CRLAnnContent, --CRLアナウンス pkiconf [19] PKIConfirmContent, --確認 nested [20] NestedMessageContent, --ネストされたメッセージ genm [21] GenMsgContent, --汎用メッセージ genp [22] GenRepContent, --汎用レスポンス error [23] ErrorMsgContent, --エラーメッセージ certConf [24] CertConfirmContent, --証明書確認 pollReq [25] PollReqContent, --ポーリングリクエスト pollRep [26] PollRepContent --ポーリングレスポンス }
PKIProtection ::= BIT STRING
ProtectedPart ::= SEQUENCE { header PKIHeader, body PKIBody }
id-PasswordBasedMac OBJECT IDENTIFIER ::= {1 2 840 113533 7 66 13} PBMParameter ::= SEQUENCE { salt OCTET STRING, -- 注：実装は、サービス拒否攻撃のリスクを減らすために、 -- この文字列の許容サイズを環境に適した値に制限しても -- よいです（MAY）。 owf AlgorithmIdentifier, -- 一方向関数（OWF）のAlgId iterationCount INTEGER, -- OWFを適用する回数 -- 注：実装は、サービス拒否攻撃のリスクを減らすために、 -- この整数の許容サイズを環境に適した値に制限しても -- よいです（MAY）。 mac AlgorithmIdentifier -- MACのAlgId（たとえば、HMAC-SHA256、AES-GMAC [RFC9481]、 } -- またはHMAC [RFC2104, RFC2202]）
id-DHBasedMac OBJECT IDENTIFIER ::= {1 2 840 113533 7 66 30} DHBMParameter ::= SEQUENCE { owf AlgorithmIdentifier, -- 一方向関数のAlgId mac AlgorithmIdentifier -- MACのAlgId（たとえば、HMAC-SHA256、AES-GMAC [RFC9481]、 } -- またはHMAC [RFC2104, RFC2202]）
NestedMessageContent ::= PKIMessages
PKIStatus ::= INTEGER { accepted (0), -- 要求したものがそのまま得られました grantedWithMods (1), -- 要求したものに近いものが得られました。相違点を確認する -- 責任は要求者にあります rejection (2), -- 得られません。詳細な情報はメッセージ内の別の場所にあります waiting (3), -- リクエストの本体部分はまだ処理されていません。後で続報が -- あるはずです（注：このステータスレスポンスを適切に処理する -- ために、[RFC4210]のセクション5.3.22で規定されている -- ポーリングのreq/rep PKIMessagesを使用してもよいです -- （MAY）。あるいは、下位のトランスポート層でのポーリングが -- この点で役立つ場合があります（MAY）） revocationWarning (4), -- このメッセージには、失効が差し迫っているという警告が -- 含まれています revocationNotification (5), -- 失効が発生したことの通知 keyUpdateWarning (6) -- CertReqMsgで指定されたoldCertIdに対する更新はすでに -- 完了しています }
PKIFailureInfo ::= BIT STRING { -- 失敗の仕方は1つではないためです！ -- 必要に応じて、将来さらにコードが追加される場合があります。 badAlg (0), -- 認識できない、またはサポートされていないアルゴリズム識別子 badMessageCheck (1), -- 完全性チェックに失敗しました（たとえば、署名が検証できません -- でした） badRequest (2), -- トランザクションが許可されていないか、サポートされていません badTime (3), -- ローカルポリシーで定義されているとおり、messageTimeが -- システム時刻に十分に近くありませんでした badCertId (4), -- 指定された条件に一致する証明書が見つかりませんでした badDataFormat (5), -- 送信されたデータの形式が誤っています wrongAuthority (6), -- リクエストで示された機関が、レスポンストークンを作成する -- 機関と異なります incorrectData (7), -- 要求者のデータが正しくありません（公証サービスの場合） missingTimeStamp (8), -- タイムスタンプが（ポリシーにより）存在すべきなのに欠落して -- いる場合 badPOP (9), -- 所有証明に失敗しました certRevoked (10), -- 証明書はすでに失効しています certConfirmed (11), -- 証明書はすでに確認されています wrongIntegrity (12), -- 完全性が無効です。署名ではなくパスワードに基づいているか、 -- またはその逆です badRecipientNonce (13), -- 受信者ノンスが無効です。欠落しているか、値が誤っています timeNotAvailable (14), -- タイムスタンプ局（TSA）の時刻源が利用できません unacceptedPolicy (15), -- 要求されたTSAポリシーはTSAでサポートされていません unacceptedExtension (16), -- 要求された拡張はTSAでサポートされていません addInfoNotAvailable (17), -- 要求された追加情報を理解できないか、利用できません badSenderNonce (18), -- 送信者ノンスが無効です。欠落しているか、サイズが誤っています badCertTemplate (19), -- 証明書テンプレートが無効か、必須の情報が欠落しています signerNotTrusted (20), -- メッセージの署名者が不明か、信頼されていません transactionIdInUse (21), -- トランザクション識別子はすでに使用されています unsupportedVersion (22), -- メッセージのバージョンはサポートされていません notAuthorized (23), -- 送信者は、先行するリクエストを行うこと、または先行する -- アクションを実行することを認可されていませんでした systemUnavail (24), -- システムが利用できないため、リクエストを処理できません systemFailure (25), -- システム障害のため、リクエストを処理できません duplicateCertReq (26) -- 重複する証明書がすでに存在するため、証明書を発行できません }
PKIStatusInfo ::= SEQUENCE { status PKIStatus, statusString PKIFreeText OPTIONAL, failInfo PKIFailureInfo OPTIONAL }
OOBCert ::= CMPCertificate
OOBCertHash ::= SEQUENCE { hashAlg [0] AlgorithmIdentifier OPTIONAL, certId [1] CertId OPTIONAL, hashVal BIT STRING -- hashValは、識別子certIDを持つ自己署名証明書のDER -- エンコーディングに対して計算されます。 }
POPODecKeyChallContent ::= SEQUENCE OF Challenge -- 暗号化鍵の証明書発行リクエストごとに1つのChallenge -- （これらのリクエストがCertReqMessagesに現れるのと同じ順序）
Challenge ::= SEQUENCE { owf AlgorithmIdentifier OPTIONAL, -- 最初のChallengeには存在しなければなりません（MUST）。 -- POPODecKeyChallContent内の後続のChallengeでは省略しても -- よいです（MAY）（省略された場合は、直前のChallengeで -- 使用されたowfを使用します） witness OCTET STRING, -- ランダムに生成されたINTEGER Aに一方向関数（owf）を適用した -- 結果（Challengeごとに異なるINTEGERを使用しなければならない -- （MUST）ことに注意してください。） challenge OCTET STRING -- Randを（証明書リクエストの対象となっている公開鍵で）暗号化 -- したもの }
-- RandはCMP Updates [RFC9480]で追加されました
Rand ::= SEQUENCE { -- Randは、POPODecKeyChallContentのチャレンジを形成するために -- 公開鍵で暗号化されます int INTEGER, -- ランダムに生成されたINTEGER A（上記） sender GeneralName -- 送信者の名前（PKIHeaderに含まれるもの） }
POPODecKeyRespContent ::= SEQUENCE OF INTEGER -- 暗号化鍵の証明書発行リクエストごとに1つのINTEGER（これらの -- リクエストがCertReqMessagesに現れるのと同じ順序）。取得 -- されたINTEGER A（上記）は、対応するChallengeの送信者に -- 返されます。
CertRepMessage ::= SEQUENCE { caPubs [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL, response SEQUENCE OF CertResponse }
CertificationRequest ::= SEQUENCE { certificationRequestInfo SEQUENCE { version INTEGER, subject Name, subjectPublicKeyInfo SEQUENCE { algorithm AlgorithmIdentifier, subjectPublicKey BIT STRING }, attributes [0] IMPLICIT SET OF Attribute }, signatureAlgorithm AlgorithmIdentifier, signature BIT STRING }
CertResponse ::= SEQUENCE { certReqId INTEGER, -- このレスポンスを対応するリクエストと照合するためのもの -- （対応するリクエストでcertReqIdが指定されていない場合は-1 -- の値を使用します。これはp10crの場合のみです） status PKIStatusInfo, certifiedKeyPair CertifiedKeyPair OPTIONAL, rspInfo OCTET STRING OPTIONAL -- CertReqMsg [RFC4211]のregInfoに対して定義された -- id-regInfo-utf8Pairs文字列と類似のもの }
CertifiedKeyPair ::= SEQUENCE { certOrEncCert CertOrEncCert, privateKey [0] EncryptedKey OPTIONAL, -- エンコーディングに関するコメントは[RFC4211]を参照してください。 -- CMP Updates [RFC9480]で行われた変更により、Encrypted Value -- から、EncryptedValueとEnvelopedDataのCHOICEである -- EncryptedKeyに変更されました。 -- 選択肢EncryptedValueを使用することは、この変更を行わない -- 構文とビット互換です。 publicationInfo [1] PKIPublicationInfo OPTIONAL }
CertOrEncCert ::= CHOICE { certificate [0] CMPCertificate, encryptedCert [1] EncryptedKey -- CMP Updates [RFC9480]で行われた変更により、Encrypted Value -- から、EncryptedValueとEnvelopedDataのCHOICEである -- EncryptedKeyに変更されました。 -- 選択肢EncryptedValueを使用することは、この変更を行わない -- 構文とビット互換です。 }
KeyRecRepContent ::= SEQUENCE { status PKIStatusInfo, newSigCert [0] CMPCertificate OPTIONAL, caCerts [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL, keyPairHist [2] SEQUENCE SIZE (1..MAX) OF CertifiedKeyPair OPTIONAL }
RevReqContent ::= SEQUENCE OF RevDetails
RevDetails ::= SEQUENCE { certDetails CertTemplate, -- 要求者が、失効を要求する証明書について可能な限り多くの -- ことを指定できるようにします -- （たとえば、serialNumberが利用できない場合のため） crlEntryDetails Extensions OPTIONAL -- 要求されたcrlEntryExtensions }
RevRepContent ::= SEQUENCE { status SEQUENCE SIZE (1..MAX) OF PKIStatusInfo, -- RevReqContentで送信されたのと同じ順序 revCerts [0] SEQUENCE SIZE (1..MAX) OF CertId OPTIONAL, -- 失効が要求されたID -- （statusと同じ順序） crls [1] SEQUENCE SIZE (1..MAX) OF CertificateList OPTIONAL -- 結果として得られるCRL（複数存在する場合があります） }
CAKeyUpdAnnContent ::= SEQUENCE { oldWithNew CMPCertificate, -- 新しい秘密鍵で署名された古い公開鍵 newWithOld CMPCertificate, -- 古い秘密鍵で署名された新しい公開鍵 newWithNew CMPCertificate -- 新しい秘密鍵で署名された新しい公開鍵 }
CertAnnContent ::= CMPCertificate
RevAnnContent ::= SEQUENCE { status PKIStatus, certId CertId, willBeRevokedAt GeneralizedTime, badSinceDate GeneralizedTime, crlDetails Extensions OPTIONAL -- CRLの追加の詳細（たとえば、CRL番号、理由、場所など） }
CRLAnnContent ::= SEQUENCE OF CertificateList
CertConfirmContent ::= SEQUENCE OF CertStatus
CertStatus ::= SEQUENCE { certHash OCTET STRING, -- 証明書の署名の作成と検証に使用されるのと同じハッシュ -- アルゴリズムを使用した、証明書のハッシュ certReqId INTEGER, -- この確認を対応するreq/repと照合するためのもの statusInfo PKIStatusInfo OPTIONAL, hashAlg [0] AlgorithmIdentifier OPTIONAL -- certHashの計算に使用するハッシュアルゴリズム -- 証明書の署名のAlgorithmIdentifierがハッシュ -- アルゴリズムを指定しているすべての場合において、 -- 使用すべきではありません（SHOULD NOT） }
PKIConfirmContent ::= NULL
-- CertReqTemplateContent、id-regCtrl-algId、id-regCtrl-algId、 -- およびid-regCtrl-rsaKeyLenは、CMP Updates [RFC9480]で追加 -- されました
CertReqTemplateContent ::= SEQUENCE { certTemplate CertTemplate, -- 事前に入力されたcertTemplate構造の要素 -- certTemplate内のSubjectPublicKeyInfoフィールドは使用しては -- なりません（MUST NOT）。 keySpec Controls OPTIONAL -- サポートされているアルゴリズムを指定するために使用しても -- よいです（MAY） -- Controls ::= SEQUENCE SIZE (1..MAX) OF AttributeTypeAndValue -- CRMF [RFC4211]で規定されているとおり }
id-regCtrl-altCertTemplate OBJECT IDENTIFIER ::= { id-regCtrl 7 } AltCertTemplate ::= AttributeTypeAndValue -- X.509v3公開鍵証明書以外の証明書のテンプレートを指定します
id-regCtrl-algId OBJECT IDENTIFIER ::= { id-regCtrl 11 } AlgIdCtrl ::= AlgorithmIdentifier -- RSA以外のサポートされているアルゴリズムを指定するために -- 使用することになります（SHALL）
id-regCtrl-rsaKeyLen OBJECT IDENTIFIER ::= { id-regCtrl 12 } RsaKeyLenCtrl ::= INTEGER (1..MAX) -- サポートされているRSA鍵長を指定するために使用することに -- なります（SHALL）
-- RootCaKeyUpdateContent、CRLSource、およびCRLStatusは、 -- CMP Updates [RFC9480]で追加されました
RootCaKeyUpdateContent ::= SEQUENCE { newWithNew CMPCertificate, -- 新しいルートCA証明書 newWithOld [0] CMPCertificate OPTIONAL, -- 古いルートCA秘密鍵で署名された、新しいルートCA公開鍵を -- 含むX.509証明書 oldWithNew [1] CMPCertificate OPTIONAL -- 新しいルートCA秘密鍵で署名された、古いルートCA公開鍵を -- 含むX.509証明書 }
CRLSource ::= CHOICE { dpn [0] DistributionPointName, issuer [1] GeneralNames }
CRLStatus ::= SEQUENCE { source CRLSource, thisUpdate Time OPTIONAL }
InfoTypeAndValue ::= SEQUENCE { infoType OBJECT IDENTIFIER, infoValue ANY DEFINED BY infoType OPTIONAL } -- InfoTypeAndValueの内容の例としては、次のものがありますが、 -- これらに限定されません（このASN.1モジュール内で -- コメントアウトを解除し、所定の環境に応じて適切に使用して -- ください）。 -- -- id-it-caProtEncCert OBJECT IDENTIFIER ::= {id-it 1} -- CAProtEncCertValue ::= CMPCertificate -- id-it-signKeyPairTypes OBJECT IDENTIFIER ::= {id-it 2} -- SignKeyPairTypesValue ::= SEQUENCE SIZE (1..MAX) OF -- AlgorithmIdentifier -- id-it-encKeyPairTypes OBJECT IDENTIFIER ::= {id-it 3} -- EncKeyPairTypesValue ::= SEQUENCE SIZE (1..MAX) OF -- AlgorithmIdentifier -- id-it-preferredSymmAlg OBJECT IDENTIFIER ::= {id-it 4} -- PreferredSymmAlgValue ::= AlgorithmIdentifier -- id-it-caKeyUpdateInfo OBJECT IDENTIFIER ::= {id-it 5} -- CAKeyUpdateInfoValue ::= CAKeyUpdAnnContent -- id-it-currentCRL OBJECT IDENTIFIER ::= {id-it 6} -- CurrentCRLValue ::= CertificateList -- id-it-unsupportedOIDs OBJECT IDENTIFIER ::= {id-it 7} -- UnsupportedOIDsValue ::= SEQUENCE SIZE (1..MAX) OF -- OBJECT IDENTIFIER -- id-it-keyPairParamReq OBJECT IDENTIFIER ::= {id-it 10} -- KeyPairParamReqValue ::= OBJECT IDENTIFIER -- id-it-keyPairParamRep OBJECT IDENTIFIER ::= {id-it 11} -- KeyPairParamRepValue ::= AlgorithmIdentifier -- id-it-revPassphrase OBJECT IDENTIFIER ::= {id-it 12} -- RevPassphraseValue ::= EncryptedKey -- - CMP Updates [RFC9480]で行われた変更により、 -- - Encrypted Valueから、EncryptedValueと -- - EnvelopedDataのCHOICEであるEncryptedKeyに変更 -- - されました。 -- - 選択肢EncryptedValueを使用することは、この変更を -- - 行わない構文とビット互換です。 -- id-it-implicitConfirm OBJECT IDENTIFIER ::= {id-it 13} -- ImplicitConfirmValue ::= NULL -- id-it-confirmWaitTime OBJECT IDENTIFIER ::= {id-it 14} -- ConfirmWaitTimeValue ::= GeneralizedTime -- id-it-origPKIMessage OBJECT IDENTIFIER ::= {id-it 15} -- OrigPKIMessageValue ::= PKIMessages -- id-it-suppLangTags OBJECT IDENTIFIER ::= {id-it 16} -- SuppLangTagsValue ::= SEQUENCE OF UTF8String -- id-it-caCerts OBJECT IDENTIFIER ::= {id-it 17} -- CaCertsValue ::= SEQUENCE SIZE (1..MAX) OF -- CMPCertificate -- - id-it-caCertsはCMP Updates [RFC9480]で追加されました -- id-it-rootCaKeyUpdate OBJECT IDENTIFIER ::= {id-it 18} -- RootCaKeyUpdateValue ::= RootCaKeyUpdateContent -- - id-it-rootCaKeyUpdateはCMP Updates [RFC9480]で追加されました -- id-it-certReqTemplate OBJECT IDENTIFIER ::= {id-it 19} -- CertReqTemplateValue ::= CertReqTemplateContent -- - id-it-certReqTemplateはCMP Updates [RFC9480]で追加されました -- id-it-rootCaCert OBJECT IDENTIFIER ::= {id-it 20} -- RootCaCertValue ::= CMPCertificate -- - id-it-rootCaCertはCMP Updates [RFC9480]で追加されました -- id-it-certProfile OBJECT IDENTIFIER ::= {id-it 21} -- CertProfileValue ::= SEQUENCE SIZE (1..MAX) OF -- UTF8String -- - id-it-certProfileはCMP Updates [RFC9480]で追加されました -- id-it-crlStatusList OBJECT IDENTIFIER ::= {id-it 22} -- CRLStatusListValue ::= SEQUENCE SIZE (1..MAX) OF -- CRLStatus -- - id-it-crlStatusListはCMP Updates [RFC9480]で追加されました -- id-it-crls OBJECT IDENTIFIER ::= {id-it 23} -- CRLsValue ::= SEQUENCE SIZE (1..MAX) OF -- CertificateList -- - id-it-crlsはCMP Updates [RFC9480]で追加されました -- -- ここで -- -- id-pkix OBJECT IDENTIFIER ::= { -- iso(1) identified-organization(3) -- dod(6) internet(1) security(5) mechanisms(5) pkix(7)} -- および -- id-it OBJECT IDENTIFIER ::= {id-pkix 4} -- -- -- この構成要素は、将来のニーズや特定の環境のために、新しい -- PKIX証明書管理プロトコルのリクエストメッセージとレスポンス -- メッセージ、または汎用（たとえば、アナウンス）メッセージを -- 定義するために使用してもよいです（MAY）。
GenMsgContent ::= SEQUENCE OF InfoTypeAndValue
-- EE、RA、またはCAによって送信される場合があります（メッセージ -- の内容によります）。上記の例のいくつかでは、通常、 -- InfoTypeAndValueの選択可能な（OPTIONAL）infoValue -- パラメーターは省略されます。受信者は、含まれているOIDのうち -- 認識できないものを自由に無視できます。EEからCAに送信される -- 場合、空の集合は、CAが望む任意の/すべての情報を送信できる -- ことを示します。
GenRepContent ::= SEQUENCE OF InfoTypeAndValue -- 受信者は、含まれているOIDのうち認識できないものを無視しても -- よいです（MAY）。
ErrorMsgContent ::= SEQUENCE { pKIStatusInfo PKIStatusInfo, errorCode INTEGER OPTIONAL, -- 実装固有のエラーコード errorDetails PKIFreeText OPTIONAL -- 実装固有のエラーの詳細 }
PollReqContent ::= SEQUENCE OF SEQUENCE { certReqId INTEGER }
PollRepContent ::= SEQUENCE OF SEQUENCE { certReqId INTEGER, checkAfter INTEGER, -- 秒単位の時間 reason PKIFreeText OPTIONAL }
-- -- CMPの操作で使用されるPKIエンティティーのための拡張鍵用途 -- 拡張。CMP Updates [RFC9480]で行われた変更により追加 -- されました -- CAとRAのためのEKUは、[RFC6402]で定義されているとおり、 -- CMCのものを再利用しています --
-- id-kp-cmcCA OBJECT IDENTIFIER ::= { id-kp 27 } -- id-kp-cmcRA OBJECT IDENTIFIER ::= { id-kp 28 } id-kp-cmKGA OBJECT IDENTIFIER ::= { id-kp 32 }
-- localKeyId属性の型と値の構文をインポートできる、PKCS #9の -- 1988 ASN.1モジュールは存在しません。したがって、CMP Updates -- [RFC9480]で行われた更新のために必要な構文をここに追加して -- います。
pkcs-9 OBJECT IDENTIFIER ::= {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) 9}
pkcs-9-at-localKeyId OBJECT IDENTIFIER ::= {pkcs-9 21}
LocalKeyIdValue ::= OCTET STRING
END -- CMPモジュールの終わり

PKIXCMP-2021 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-cmp2021-02(100) } DEFINITIONS EXPLICIT TAGS ::= BEGIN IMPORTS
AttributeSet{}, SingleAttribute{}, Extensions{}, EXTENSION, ATTRIBUTE FROM PKIX-CommonTypes-2009 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkixCommon-02(57)}
AlgorithmIdentifier{}, SIGNATURE-ALGORITHM, ALGORITHM, DIGEST-ALGORITHM, MAC-ALGORITHM FROM AlgorithmInformation-2009 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-algorithmInformation-02(58)}
Certificate, CertificateList, Time, id-kp FROM PKIX1Explicit-2009 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-explicit-02(51)}
DistributionPointName, GeneralNames, GeneralName, KeyIdentifier FROM PKIX1Implicit-2009 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-implicit-02(59)}
CertTemplate, PKIPublicationInfo, EncryptedKey, CertId, CertReqMessages, Controls, RegControlSet, id-regCtrl FROM PKIXCRMF-2009 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-crmf2005-02(55) } -- EncryptedKeyのインポートは、CMP Updates [RFC9480]で -- 行われた更新により追加されています。EncryptedValueは -- もはやインポートする必要がないため、ここでは削除されて -- います。
-- この仕様の付録Cで成文化されている、CRMFに対する振る舞いの -- 明確化も参照してください。
CertificationRequest FROM PKCS-10 {iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkcs10-2009(69)} -- （[RFC2986]で1993 ASN.1構文とIMPLICITタグを用いて規定されて -- います）。あるいは、実装者は[RFC2986]の構文をこのモジュール -- に直接含めることもできます。
localKeyId FROM PKCS-9 {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) modules(0) pkcs-9(1)} -- localKeyIdのインポートは、CMP Updates [RFC9480]で行われた -- 更新により追加されています。
EnvelopedData, SignedData FROM CryptographicMessageSyntax-2009 {iso(1) member-body(2) us(840) rsadsi(113549) pkcs(1) pkcs-9(9) smime(16) modules(0) id-mod-cms-2004-02(41)} -- EnvelopedDataとSignedDataのインポートは、CMP Updates -- [RFC9480]で行われた更新により追加されています。 ;
-- モジュールの残りの部分には、ローカルで定義されたOIDと -- 構成要素が含まれています。
CMPCertificate ::= CHOICE { x509v3PKCert Certificate, ... } -- この構文は、"Certificate"の標準的なX.509の定義と -- ワイヤー上のビットレベルで互換性がありつつ、そのような -- 汎用性をサポートする必要が生じた場合に、この証明書管理 -- プロトコルの中で将来の証明書タイプ（X.509属性証明書、 -- カード検証可能な証明書、その他の種類の証明書など）を -- 扱える可能性を残しています。他の証明書タイプをサポート -- する必要性を予見しない実装は、望むなら、このASN.1 -- モジュールをコンパイルする前に上記の構造をコメント -- アウトし、次の構造の"コメントアウトを解除"しても -- よいです（MAY）。（これを行わない実装との相互運用性は、 -- この変更による影響を受けないことに注意してください。）
-- CMPCertificate ::= Certificate
PKIMessage ::= SEQUENCE { header PKIHeader, body PKIBody, protection [0] PKIProtection OPTIONAL, extraCerts [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL }
PKIMessages ::= SEQUENCE SIZE (1..MAX) OF PKIMessage
PKIHeader ::= SEQUENCE { pvno INTEGER { cmp1999(1), cmp2000(2), cmp2012(3) }, sender GeneralName, -- 送信者を識別します recipient GeneralName, -- 意図された受信者を識別します messageTime [0] GeneralizedTime OPTIONAL, -- このメッセージの生成時刻（トランスポートが"適切"である、 -- つまり受信時にもその時刻が意味を持つと送信者が考える場合 -- に使用されます） protectionAlg [1] AlgorithmIdentifier{ALGORITHM, {...}} OPTIONAL, -- 保護ビットの計算に使用されるアルゴリズム senderKID [2] KeyIdentifier OPTIONAL, recipKID [3] KeyIdentifier OPTIONAL, -- 保護に使用される特定の鍵を識別するためのもの transactionID [4] OCTET STRING OPTIONAL, -- トランザクションを識別します。つまり、これは対応する -- リクエスト、レスポンス、certConf、PKIConfの各メッセージで -- 同じになります senderNonce [5] OCTET STRING OPTIONAL, recipNonce [6] OCTET STRING OPTIONAL, -- リプレイ保護を提供するために使用されるノンスです。 -- senderNonceはこのメッセージの作成者によって挿入されます。 -- recipNonceは、このメッセージの意図された受信者によって、 -- 関連するメッセージに以前挿入されたノンスです。 freeText [7] PKIFreeText OPTIONAL, -- これは、コンテキスト固有の指示を示すために使用できます -- （このフィールドは人間が読むことを意図しています） generalInfo [8] SEQUENCE SIZE (1..MAX) OF InfoTypeAndValue OPTIONAL -- これは、コンテキスト固有の情報を伝達するために使用できます -- （このフィールドは主に人間が読むことを意図していません） }
PKIFreeText ::= SEQUENCE SIZE (1..MAX) OF UTF8String -- UTF-8文字列[RFC3629]としてエンコードされたテキスト
PKIBody ::= CHOICE { -- メッセージ固有の本体要素 ir [0] CertReqMessages, --初期化リクエスト ip [1] CertRepMessage, --初期化レスポンス cr [2] CertReqMessages, --証明書発行リクエスト cp [3] CertRepMessage, --証明書発行レスポンス p10cr [4] CertificationRequest, --[RFC2986]からインポート popdecc [5] POPODecKeyChallContent, --POPチャレンジ popdecr [6] POPODecKeyRespContent, --POPレスポンス kur [7] CertReqMessages, --鍵更新リクエスト kup [8] CertRepMessage, --鍵更新レスポンス krr [9] CertReqMessages, --鍵回復リクエスト krp [10] KeyRecRepContent, --鍵回復レスポンス rr [11] RevReqContent, --失効リクエスト rp [12] RevRepContent, --失効レスポンス ccr [13] CertReqMessages, --相互証明書リクエスト ccp [14] CertRepMessage, --相互証明書レスポンス ckuann [15] CAKeyUpdAnnContent, --CA鍵更新アナウンス cann [16] CertAnnContent, --証明書アナウンス rann [17] RevAnnContent, --失効アナウンス crlann [18] CRLAnnContent, --CRLアナウンス pkiconf [19] PKIConfirmContent, --確認 nested [20] NestedMessageContent, --ネストされたメッセージ genm [21] GenMsgContent, --汎用メッセージ genp [22] GenRepContent, --汎用レスポンス error [23] ErrorMsgContent, --エラーメッセージ certConf [24] CertConfirmContent, --証明書確認 pollReq [25] PollReqContent, --ポーリングリクエスト pollRep [26] PollRepContent --ポーリングレスポンス }
PKIProtection ::= BIT STRING
ProtectedPart ::= SEQUENCE { header PKIHeader, body PKIBody }
id-PasswordBasedMac OBJECT IDENTIFIER ::= { iso(1) member-body(2) usa(840) nt(113533) nsn(7) algorithms(66) 13 } PBMParameter ::= SEQUENCE { salt OCTET STRING, -- 注：実装は、サービス拒否攻撃のリスクを減らすために、 -- この文字列の許容サイズを環境に適した値に制限しても -- よいです（MAY）。 owf AlgorithmIdentifier{DIGEST-ALGORITHM, {...}}, -- 一方向関数のAlgId iterationCount INTEGER, -- OWFを適用する回数 -- 注：実装は、サービス拒否攻撃のリスクを減らすために、 -- この整数の許容サイズを環境に適した値に制限しても -- よいです（MAY）。 mac AlgorithmIdentifier{MAC-ALGORITHM, {...}} -- MACのAlgId（たとえば、HMAC-SHA256、AES-GMAC [RFC9481]、 -- またはHMAC [RFC2104, RFC2202]） }
id-DHBasedMac OBJECT IDENTIFIER ::= { iso(1) member-body(2) usa(840) nt(113533) nsn(7) algorithms(66) 30 } DHBMParameter ::= SEQUENCE { owf AlgorithmIdentifier{DIGEST-ALGORITHM, {...}}, -- 一方向関数のAlgId mac AlgorithmIdentifier{MAC-ALGORITHM, {...}} -- MACのAlgId（たとえば、HMAC-SHA256、AES-GMAC [RFC9481]、 -- またはHMAC [RFC2104, RFC2202]） }
PKIStatus ::= INTEGER { accepted (0), -- 要求したものがそのまま得られました grantedWithMods (1), -- 要求したものに近いものが得られました。相違点を確認する -- 責任は要求者にあります rejection (2), -- 得られません。詳細な情報はメッセージ内の別の場所にあります waiting (3), -- リクエストの本体部分はまだ処理されていません。後で続報が -- あるはずです（注：このステータスレスポンスを適切に処理する -- ために、[RFC4210]のセクション5.3.22で規定されている -- ポーリングのreq/rep PKIMessagesを使用してもよいです -- （MAY）。あるいは、下位のトランスポート層でのポーリングが -- この点で役立つ場合があります（MAY）） revocationWarning (4), -- このメッセージには、失効が差し迫っているという警告が -- 含まれています revocationNotification (5), -- 失効が発生したことの通知 keyUpdateWarning (6) -- CertReqMsgで指定されたoldCertIdに対する更新はすでに -- 完了しています }
PKIFailureInfo ::= BIT STRING { -- 失敗の仕方は1つではないためです！ -- 必要に応じて、将来さらにコードが追加される場合があります。 badAlg (0), -- 認識できない、またはサポートされていないアルゴリズム識別子 badMessageCheck (1), -- 完全性チェックに失敗しました（たとえば、署名が検証できません -- でした） badRequest (2), -- トランザクションが許可されていないか、サポートされていません badTime (3), -- ローカルポリシーで定義されているとおり、messageTimeが -- システム時刻に十分に近くありませんでした badCertId (4), -- 指定された条件に一致する証明書が見つかりませんでした badDataFormat (5), -- 送信されたデータの形式が誤っています wrongAuthority (6), -- リクエストで示された機関が、レスポンストークンを作成する -- 機関と異なります incorrectData (7), -- 要求者のデータが正しくありません（公証サービスの場合） missingTimeStamp (8), -- タイムスタンプが（ポリシーにより）存在すべきなのに欠落して -- いる場合 badPOP (9), -- 所有証明に失敗しました certRevoked (10), -- 証明書はすでに失効しています certConfirmed (11), -- 証明書はすでに確認されています wrongIntegrity (12), -- 完全性が無効です。署名ではなくパスワードに基づいているか、 -- またはその逆です badRecipientNonce (13), -- 受信者ノンスが無効です。欠落しているか、値が誤っています timeNotAvailable (14), -- TSAの時刻源が利用できません unacceptedPolicy (15), -- 要求されたTSAポリシーはTSAでサポートされていません unacceptedExtension (16), -- 要求された拡張はTSAでサポートされていません addInfoNotAvailable (17), -- 要求された追加情報を理解できないか、利用できません badSenderNonce (18), -- 送信者ノンスが無効です。欠落しているか、サイズが誤っています badCertTemplate (19), -- 証明書テンプレートが無効か、必須の情報が欠落しています signerNotTrusted (20), -- メッセージの署名者が不明か、信頼されていません transactionIdInUse (21), -- トランザクション識別子はすでに使用されています unsupportedVersion (22), -- メッセージのバージョンはサポートされていません notAuthorized (23), -- 送信者は、先行するリクエストを行うこと、または先行する -- アクションを実行することを認可されていませんでした systemUnavail (24), -- システムが利用できないため、リクエストを処理できません systemFailure (25), -- システム障害のため、リクエストを処理できません duplicateCertReq (26) -- 重複する証明書がすでに存在するため、証明書を発行できません }
PKIStatusInfo ::= SEQUENCE { status PKIStatus, statusString PKIFreeText OPTIONAL, failInfo PKIFailureInfo OPTIONAL }
OOBCert ::= CMPCertificate
OOBCertHash ::= SEQUENCE { hashAlg [0] AlgorithmIdentifier{DIGEST-ALGORITHM, {...}} OPTIONAL, certId [1] CertId OPTIONAL, hashVal BIT STRING -- hashValは、識別子certIDを持つ自己署名証明書のDER -- エンコーディングに対して計算されます。 }
POPODecKeyChallContent ::= SEQUENCE OF Challenge -- 暗号化鍵の証明書発行リクエストごとに1つのChallenge -- （これらのリクエストがCertReqMessagesに現れるのと同じ順序）
Challenge ::= SEQUENCE { owf AlgorithmIdentifier{DIGEST-ALGORITHM, {...}} OPTIONAL, -- 最初のChallengeには存在しなければなりません（MUST）。 -- POPODecKeyChallContent内の後続のChallengeでは省略しても -- よいです（MAY）（省略された場合は、直前のChallengeで -- 使用されたowfを使用します） witness OCTET STRING, -- ランダムに生成されたINTEGER Aに一方向関数（owf）を適用した -- 結果（Challengeごとに異なるINTEGERを使用しなければならない -- （MUST）ことに注意してください。） challenge OCTET STRING -- Randを（証明書リクエストの対象となっている公開鍵で）暗号化 -- したもの }
-- RandはCMP Updates [RFC9480]で追加されました
Rand ::= SEQUENCE { -- Randは、POPODecKeyChallContentのチャレンジを形成するために -- 公開鍵で暗号化されます int INTEGER, -- ランダムに生成されたINTEGER A（上記） sender GeneralName -- 送信者の名前（PKIHeaderに含まれるもの） }
POPODecKeyRespContent ::= SEQUENCE OF INTEGER -- 暗号化鍵の証明書発行リクエストごとに1つのINTEGER（これらの -- リクエストがCertReqMessagesに現れるのと同じ順序）。取得 -- されたINTEGER A（上記）は、対応するChallengeの送信者に -- 返されます。
CertRepMessage ::= SEQUENCE { caPubs [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL, response SEQUENCE OF CertResponse }
CertResponse ::= SEQUENCE { certReqId INTEGER, -- このレスポンスを対応するリクエストと照合するためのもの -- （対応するリクエストでcertReqIdが指定されていない場合は-1 -- の値を使用します。これはp10crの場合のみです） status PKIStatusInfo, certifiedKeyPair CertifiedKeyPair OPTIONAL, rspInfo OCTET STRING OPTIONAL -- CertReqMsg [RFC4211]のregInfoに対して定義された -- id-regInfo-utf8Pairs文字列と類似のもの }
CertifiedKeyPair ::= SEQUENCE { certOrEncCert CertOrEncCert, privateKey [0] EncryptedKey OPTIONAL, -- エンコーディングに関するコメントは[RFC4211]を参照してください。 -- CMP Updates [RFC9480]で行われた変更により、Encrypted Value -- から、EncryptedValueとEnvelopedDataのCHOICEである -- EncryptedKeyに変更されました。 -- 選択肢EncryptedValueを使用することは、この変更を行わない -- 構文とビット互換です。 publicationInfo [1] PKIPublicationInfo OPTIONAL }
CertOrEncCert ::= CHOICE { certificate [0] CMPCertificate, encryptedCert [1] EncryptedKey -- CMP Updates [RFC9480]で行われた変更により、Encrypted Value -- から、EncryptedValueとEnvelopedDataのCHOICEである -- EncryptedKeyに変更されました。 -- 選択肢EncryptedValueを使用することは、この変更を行わない -- 構文とビット互換です。 }
KeyRecRepContent ::= SEQUENCE { status PKIStatusInfo, newSigCert [0] CMPCertificate OPTIONAL, caCerts [1] SEQUENCE SIZE (1..MAX) OF CMPCertificate OPTIONAL, keyPairHist [2] SEQUENCE SIZE (1..MAX) OF CertifiedKeyPair OPTIONAL }
RevReqContent ::= SEQUENCE OF RevDetails
RevDetails ::= SEQUENCE { certDetails CertTemplate, -- 要求者が、失効を要求する証明書について可能な限り多くの -- ことを指定できるようにします -- （たとえば、serialNumberが利用できない場合のため） crlEntryDetails Extensions{{...}} OPTIONAL -- 要求されたcrlEntryExtensions }
RevRepContent ::= SEQUENCE { status SEQUENCE SIZE (1..MAX) OF PKIStatusInfo, -- RevReqContentで送信されたのと同じ順序 revCerts [0] SEQUENCE SIZE (1..MAX) OF CertId OPTIONAL, -- 失効が要求されたID -- （statusと同じ順序） crls [1] SEQUENCE SIZE (1..MAX) OF CertificateList OPTIONAL -- 結果として得られるCRL（複数存在する場合があります） }
CAKeyUpdAnnContent ::= SEQUENCE { oldWithNew CMPCertificate, -- 新しい秘密鍵で署名された古い公開鍵 newWithOld CMPCertificate, -- 古い秘密鍵で署名された新しい公開鍵 newWithNew CMPCertificate -- 新しい秘密鍵で署名された新しい公開鍵 }
CertAnnContent ::= CMPCertificate
RevAnnContent ::= SEQUENCE { status PKIStatus, certId CertId, willBeRevokedAt GeneralizedTime, badSinceDate GeneralizedTime, crlDetails Extensions{{...}} OPTIONAL -- CRLの追加の詳細（たとえば、CRL番号、理由、場所など） }
CRLAnnContent ::= SEQUENCE OF CertificateList PKIConfirmContent ::= NULL
NestedMessageContent ::= PKIMessages
-- CertReqTemplateContent、AttributeTypeAndValue、 -- ExpandedRegControlSet、id-regCtrl-altCertTemplate、 -- AltCertTemplate、regCtrl-algId、id-regCtrl-algId、AlgIdCtrl、 -- regCtrl-rsaKeyLen、id-regCtrl-rsaKeyLen、およびRsaKeyLenCtrl -- は、CMP Updates [RFC9480]で追加されました
CertReqTemplateContent ::= SEQUENCE { certTemplate CertTemplate, -- 事前に入力されたcertTemplate構造の要素 -- certTemplate内のSubjectPublicKeyInfoフィールドは使用しては -- なりません（MUST NOT）。 keySpec Controls OPTIONAL -- サポートされているアルゴリズムを指定するために使用しても -- よいです（MAY） -- Controls ::= SEQUENCE SIZE (1..MAX) OF AttributeTypeAndValue -- CRMF [RFC4211]で規定されているとおり }
AttributeTypeAndValue ::= SingleAttribute{{ ... }}
ExpandedRegControlSet ATTRIBUTE ::= { RegControlSet | regCtrl-altCertTemplate | regCtrl-algId | regCtrl-rsaKeyLen, ... }
regCtrl-altCertTemplate ATTRIBUTE ::= { TYPE AltCertTemplate IDENTIFIED BY id-regCtrl-altCertTemplate }
id-regCtrl-altCertTemplate OBJECT IDENTIFIER ::= { id-regCtrl 7 }
AltCertTemplate ::= AttributeTypeAndValue -- X.509v3公開鍵証明書以外の証明書のテンプレートを指定します
regCtrl-algId ATTRIBUTE ::= { TYPE AlgIdCtrl IDENTIFIED BY id-regCtrl-algId }
id-regCtrl-algId OBJECT IDENTIFIER ::= { id-regCtrl 11 }
AlgIdCtrl ::= AlgorithmIdentifier{ALGORITHM, {...}} -- RSA以外のサポートされているアルゴリズムを指定するために -- 使用することになります（SHALL）
regCtrl-rsaKeyLen ATTRIBUTE ::= { TYPE RsaKeyLenCtrl IDENTIFIED BY id-regCtrl-rsaKeyLen }
id-regCtrl-rsaKeyLen OBJECT IDENTIFIER ::= { id-regCtrl 12 }
RsaKeyLenCtrl ::= INTEGER (1..MAX) -- サポートされているRSA鍵長を指定するために使用することに -- なります（SHALL）
-- RootCaKeyUpdateContent、CRLSource、およびCRLStatusは、 -- CMP Updates [RFC9480]で追加されました
RootCaKeyUpdateContent ::= SEQUENCE { newWithNew CMPCertificate, -- 新しいルートCA証明書 newWithOld [0] CMPCertificate OPTIONAL, -- 古いルートCA秘密鍵で署名された、新しいルートCA公開鍵を -- 含むX.509証明書 oldWithNew [1] CMPCertificate OPTIONAL -- 新しいルートCA秘密鍵で署名された、古いルートCA公開鍵を -- 含むX.509証明書 }
CRLSource ::= CHOICE { dpn [0] DistributionPointName, issuer [1] GeneralNames }
CRLStatus ::= SEQUENCE { source CRLSource, thisUpdate Time OPTIONAL }
INFO-TYPE-AND-VALUE ::= TYPE-IDENTIFIER
InfoTypeAndValue ::= SEQUENCE { infoType INFO-TYPE-AND-VALUE. &id({SupportedInfoSet}), infoValue INFO-TYPE-AND-VALUE. &Type({SupportedInfoSet}{@infoType}) }
SupportedInfoSet INFO-TYPE-AND-VALUE ::= { ... }
-- InfoTypeAndValueの内容の例としては、次のものがありますが、 -- これらに限定されません（このASN.1モジュール内で -- コメントアウトを解除し、所定の環境に応じて適切に使用して -- ください）。 -- -- id-it-caProtEncCert OBJECT IDENTIFIER ::= {id-it 1} -- CAProtEncCertValue ::= CMPCertificate -- id-it-signKeyPairTypes OBJECT IDENTIFIER ::= {id-it 2} -- SignKeyPairTypesValue ::= SEQUENCE SIZE (1..MAX) OF -- AlgorithmIdentifier{{...}} -- id-it-encKeyPairTypes OBJECT IDENTIFIER ::= {id-it 3} -- EncKeyPairTypesValue ::= SEQUENCE SIZE (1..MAX) OF -- AlgorithmIdentifier{{...}} -- id-it-preferredSymmAlg OBJECT IDENTIFIER ::= {id-it 4} -- PreferredSymmAlgValue ::= AlgorithmIdentifier{{...}} -- id-it-caKeyUpdateInfo OBJECT IDENTIFIER ::= {id-it 5} -- CAKeyUpdateInfoValue ::= CAKeyUpdAnnContent -- id-it-currentCRL OBJECT IDENTIFIER ::= {id-it 6} -- CurrentCRLValue ::= CertificateList -- id-it-unsupportedOIDs OBJECT IDENTIFIER ::= {id-it 7} -- UnsupportedOIDsValue ::= SEQUENCE SIZE (1..MAX) OF -- OBJECT IDENTIFIER -- id-it-keyPairParamReq OBJECT IDENTIFIER ::= {id-it 10} -- KeyPairParamReqValue ::= OBJECT IDENTIFIER -- id-it-keyPairParamRep OBJECT IDENTIFIER ::= {id-it 11} -- KeyPairParamRepValue ::= AlgorithmIdentifier{{...}} -- id-it-revPassphrase OBJECT IDENTIFIER ::= {id-it 12} -- RevPassphraseValue ::= EncryptedKey -- - CMP Updates [RFC9480]で行われた変更により、 -- - Encrypted Valueから、EncryptedValueと -- - EnvelopedDataのCHOICEであるEncryptedKeyに変更 -- - されました -- - 選択肢EncryptedValueを使用することは、この変更を -- - 行わない構文とビット互換です -- id-it-implicitConfirm OBJECT IDENTIFIER ::= {id-it 13} -- ImplicitConfirmValue ::= NULL -- id-it-confirmWaitTime OBJECT IDENTIFIER ::= {id-it 14} -- ConfirmWaitTimeValue ::= GeneralizedTime -- id-it-origPKIMessage OBJECT IDENTIFIER ::= {id-it 15} -- OrigPKIMessageValue ::= PKIMessages -- id-it-suppLangTags OBJECT IDENTIFIER ::= {id-it 16} -- SuppLangTagsValue ::= SEQUENCE OF UTF8String -- id-it-caCerts OBJECT IDENTIFIER ::= {id-it 17} -- CaCertsValue ::= SEQUENCE SIZE (1..MAX) OF -- CMPCertificate -- - id-it-caCertsはCMP Updates [RFC9480]で追加されました -- id-it-rootCaKeyUpdate OBJECT IDENTIFIER ::= {id-it 18} -- RootCaKeyUpdateValue ::= RootCaKeyUpdateContent -- - id-it-rootCaKeyUpdateはCMP Updates [RFC9480]で追加されました -- id-it-certReqTemplate OBJECT IDENTIFIER ::= {id-it 19} -- CertReqTemplateValue ::= CertReqTemplateContent -- - id-it-certReqTemplateはCMP Updates [RFC9480]で追加されました -- id-it-rootCaCert OBJECT IDENTIFIER ::= {id-it 20} -- RootCaCertValue ::= CMPCertificate -- - id-it-rootCaCertはCMP Updates [RFC9480]で追加されました -- id-it-certProfile OBJECT IDENTIFIER ::= {id-it 21} -- CertProfileValue ::= SEQUENCE SIZE (1..MAX) OF -- UTF8String -- - id-it-certProfileはCMP Updates [RFC9480]で追加されました -- id-it-crlStatusList OBJECT IDENTIFIER ::= {id-it 22} -- CRLStatusListValue ::= SEQUENCE SIZE (1..MAX) OF -- CRLStatus -- - id-it-crlStatusListはCMP Updates [RFC9480]で追加されました -- id-it-crls OBJECT IDENTIFIER ::= {id-it 23} -- CRLsValue ::= SEQUENCE SIZE (1..MAX) OF -- CertificateList -- - id-it-crlsはCMP Updates [RFC9480]で追加されました -- -- ここで -- -- id-pkix OBJECT IDENTIFIER ::= { -- iso(1) identified-organization(3) -- dod(6) internet(1) security(5) mechanisms(5) pkix(7)} -- および -- id-it OBJECT IDENTIFIER ::= {id-pkix 4} -- -- -- この構成要素は、将来のニーズや特定の環境のために、新しい -- PKIX証明書管理プロトコルのリクエストメッセージとレスポンス -- メッセージ、または汎用（たとえば、アナウンス）メッセージを -- 定義するために使用してもよいです（MAY）。
GenMsgContent ::= SEQUENCE OF InfoTypeAndValue
-- EE、RA、またはCAによって送信される場合があります（メッセージ -- の内容によります）。上記の例のいくつかでは、通常、 -- InfoTypeAndValueの選択可能な（OPTIONAL）infoValue -- パラメーターは省略されます。受信者は、含まれているOIDのうち -- 認識できないものを自由に無視できます。EEからCAに送信される -- 場合、空の集合は、CAが望む任意の/すべての情報を送信できる -- ことを示します。
GenRepContent ::= SEQUENCE OF InfoTypeAndValue -- 受信者は、含まれているOIDのうち認識できないものを無視しても -- よいです（MAY）。
ErrorMsgContent ::= SEQUENCE { pKIStatusInfo PKIStatusInfo, errorCode INTEGER OPTIONAL, -- 実装固有のエラーコード errorDetails PKIFreeText OPTIONAL -- 実装固有のエラーの詳細 }
CertConfirmContent ::= SEQUENCE OF CertStatus
CertStatus ::= SEQUENCE { certHash OCTET STRING, -- 証明書の署名の作成と検証に使用されるのと同じハッシュ -- アルゴリズムを使用した、証明書のハッシュ certReqId INTEGER, -- この確認を対応するreq/repと照合するためのもの statusInfo PKIStatusInfo OPTIONAL, hashAlg [0] AlgorithmIdentifier{DIGEST-ALGORITHM, {...}} OPTIONAL -- certHashの計算に使用するハッシュアルゴリズム -- 証明書の署名のAlgorithmIdentifierがハッシュ -- アルゴリズムを指定しているすべての場合において、 -- 使用すべきではありません（SHOULD NOT） }
PollReqContent ::= SEQUENCE OF SEQUENCE { certReqId INTEGER }
PollRepContent ::= SEQUENCE OF SEQUENCE { certReqId INTEGER, checkAfter INTEGER, -- 秒単位の時間 reason PKIFreeText OPTIONAL }
-- -- CMPの操作で使用されるPKIエンティティーのための拡張鍵用途 -- 拡張。CMP Updates [RFC9480]で行われた変更により追加 -- されました -- CAとRAのためのEKUは、[RFC6402]で定義されているとおり、 -- CMCのものを再利用しています --
-- id-kp-cmcCA OBJECT IDENTIFIER ::= { id-kp 27 } -- id-kp-cmcRA OBJECT IDENTIFIER ::= { id-kp 28 } id-kp-cmKGA OBJECT IDENTIFIER ::= { id-kp 32 }
END
